#!/usr/bin/env python3
"""patch18: 加盟店の個別ページ(member.html)新設、カードの店名をリンク化、ラベルに公式サイトURL。
既定はdry-run。--applyで書く。全アンカー期待1件。member.htmlが既に在れば書かない。
"""
import sys, subprocess, tempfile, os, re

APPLY = "--apply" in sys.argv
EDITS = [('workers/hs-verify-gate/src/worker.js', 'const OPERATOR_LABELS = {\n  "https://mcp.horizonshield.dev/mcp":     { ja: "KIRA\\u9069\\u6b63\\u8a3a\\u65ad", en: "KIRA fair price audit (the flagship MCP server)" },\n  "https://web.horizonshield.dev/mcp":     { ja: "KIRA\\u76f8\\u8ac7\\u7a93\\u53e3", en: "KIRA intake desk for renovation questions" },\n  "https://hearing.horizonshield.dev/mcp": { ja: "YAKUMO\\u52a0\\u76df\\u5e97\\u30c7\\u30a3\\u30ec\\u30af\\u30c8\\u30ea", en: "YAKUMO verified contractor directory" },\n  "https://gate.horizonshield.dev/mcp":    { ja: "\\u691c\\u8a3c\\u30b2\\u30fc\\u30c8\\uff08\\u3053\\u306e\\u691c\\u67fb\\u6a5f\\u81ea\\u8eab\\uff09", en: "The verification gate, measuring itself" },\n  "https://p001.horizonshield.dev/mcp":    { ja: "\\u52a0\\u76df\\u5e97\\uff08\\u63b2\\u8f09\\u6e96\\u5099\\u4e2d\\uff09", en: "Member firm, name pending consent" },\n  "https://p002.horizonshield.dev/mcp":    { ja: "\\u52a0\\u76df\\u5e97\\uff08\\u63b2\\u8f09\\u6e96\\u5099\\u4e2d\\uff09", en: "Member firm, name pending consent" }\n};', 'const OPERATOR_LABELS = {\n  "https://mcp.horizonshield.dev/mcp":     { ja: "KIRA\\u9069\\u6b63\\u8a3a\\u65ad", en: "KIRA fair price audit (the flagship MCP server)", url: "https://shield.the-horizons-innovation.com" },\n  "https://web.horizonshield.dev/mcp":     { ja: "KIRA\\u76f8\\u8ac7\\u7a93\\u53e3", en: "KIRA intake desk for renovation questions", url: "https://shield.the-horizons-innovation.com" },\n  "https://hearing.horizonshield.dev/mcp": { ja: "YAKUMO\\u52a0\\u76df\\u5e97\\u30c7\\u30a3\\u30ec\\u30af\\u30c8\\u30ea", en: "YAKUMO verified contractor directory", url: "https://shield.the-horizons-innovation.com/yakumo/" },\n  "https://gate.horizonshield.dev/mcp":    { ja: "\\u691c\\u8a3c\\u30b2\\u30fc\\u30c8\\uff08\\u3053\\u306e\\u691c\\u67fb\\u6a5f\\u81ea\\u8eab\\uff09", en: "The verification gate, measuring itself", url: "https://shield.the-horizons-innovation.com/verify-directory/" },\n  "https://p001.horizonshield.dev/mcp":    { ja: "\\u52a0\\u76df\\u5e97\\uff08\\u63b2\\u8f09\\u6e96\\u5099\\u4e2d\\uff09", en: "Member firm, name pending consent" },\n  "https://p002.horizonshield.dev/mcp":    { ja: "\\u52a0\\u76df\\u5e97\\uff08\\u63b2\\u8f09\\u6e96\\u5099\\u4e2d\\uff09", en: "Member firm, name pending consent" }\n};', 'labels url fields'), ('verify-directory/index.html', '      const nm = document.createElement("span"); nm.className = "regname";\n      nm.textContent = (r.operator_label && r.operator_label.ja) ? r.operator_label.ja : r.endpoint;\n      top.appendChild(nm);', '      const nm = document.createElement("a"); nm.className = "regname";\n      nm.href = "member.html?endpoint=" + encodeURIComponent(r.endpoint);\n      nm.textContent = (r.operator_label && r.operator_label.ja) ? r.operator_label.ja : r.endpoint;\n      top.appendChild(nm);', 'card name link'), ('verify-directory/index.html', '.regmeta .mono{opacity:.75}', '.regmeta .mono{opacity:.75}\na.regname{color:inherit;border-bottom:1px dashed rgba(255,255,255,.35)}\na.regname:hover{border-bottom-style:solid}', 'name link css')]
MEMBER_PATH = "verify-directory/member.html"
MEMBER_CONTENT = '<!doctype html>\n<html lang="ja">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>加盟店ページ | HORIZON SHIELD verify directory</title>\n<style>\n:root{\n  --bg:#08080a; --bg-2:#0d0d10; --surface:#121216;\n  --line:rgba(255,255,255,.07); --line-2:rgba(255,255,255,.12);\n  --ink:#f4f4f5; --ink-2:#a9a9b3; --ink-3:#6f6f7a;\n  --emerald:#34d399; --amber:#fbbf24; --slate:#94a3b8;\n  --mono:\'JetBrains Mono\',ui-monospace,SFMono-Regular,Menlo,monospace;\n  --sans:\'Inter\',system-ui,-apple-system,sans-serif;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.62;-webkit-font-smoothing:antialiased;\n  background-image:radial-gradient(900px 500px at 82% -8%,rgba(52,211,153,.10),transparent 60%);background-attachment:fixed}\n.wrap{max-width:860px;margin:0 auto;padding:0 26px}\na{color:inherit;text-decoration:none}\n.mono{font-family:var(--mono)}\nheader{position:sticky;top:0;background:rgba(8,8,10,.74);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}\n.bar{display:flex;align-items:center;justify-content:space-between;height:58px}\n.logo{font-weight:700;font-size:15px}\n.logo .sub{color:var(--ink-3);font-weight:500;font-size:11px;font-family:var(--mono)}\n.back{font-size:13.5px;color:var(--ink-2)}\n.back:hover{color:var(--ink)}\n.card{background:var(--surface);border:1px solid var(--line-2);border-radius:14px;padding:26px;margin:26px 0}\nh1{font-size:1.55rem;letter-spacing:-.02em}\n.desc{color:var(--ink-2);margin-top:6px}\n.eprow{margin-top:12px;font-size:.8rem;color:var(--ink-3);word-break:break-all}\n.badge{display:inline-block;font-size:.78rem;padding:3px 12px;border-radius:999px;border:1px solid;margin-left:10px;vertical-align:middle}\n.b-pass{color:#7ee2a8;border-color:#2f6f4a}\n.b-pend{color:#e2c97e;border-color:#6f5c2f}\n.b-none{color:#9aa4b2;border-color:#3a4250}\n.sitelink{display:inline-block;margin-top:14px;border:1px solid var(--line-2);border-radius:8px;padding:7px 14px;font-size:.85rem;color:var(--ink-2)}\n.sitelink:hover{color:var(--ink);border-color:var(--ink-3)}\nh2{font-size:1.05rem;margin-bottom:10px}\ntable{width:100%;border-collapse:collapse;font-size:.83rem}\nth{color:var(--ink-3);font-weight:500;text-align:left}\nth,td{padding:8px 10px;border-bottom:1px solid var(--line)}\n.sha{font-family:var(--mono);font-size:.68rem;color:var(--ink-3);word-break:break-all}\n.note{color:var(--ink-2);font-size:.84rem;margin:8px 0}\n.cmd{background:var(--bg-2);border:1px solid var(--line);border-radius:8px;padding:12px 14px;font-family:var(--mono);font-size:.72rem;overflow-x:auto;white-space:pre;margin-top:8px}\nfooter{color:var(--ink-3);font-size:.78rem;padding:30px 0 50px}\n</style>\n</head>\n<body>\n<header><div class="wrap bar">\n  <div class="logo">HORIZON SHIELD <span class="sub">/ verify</span></div>\n  <a class="back" href="./">一覧へ戻る</a>\n</div></header>\n<section><div class="wrap">\n  <div id="content"><p class="note" style="margin-top:26px">読み込み中…</p></div>\n  <div class="card">\n    <h2>このページが証明すること、しないこと</h2>\n    <p class="note">ここに並ぶ判定は、毎晩の自動測定の記録だ。掲載は推薦ではない。名前と説明は運営者が付けた表示名であり、測定値ではない。同じ注記はregister APIの応答にも書いてある。</p>\n    <p class="note">各行の record_sha256 は誰でも再計算して照合できる。下の検証コマンドがそのままそれをやる。運営者を信用する必要はない。</p>\n  </div>\n  <div class="card">\n    <h2>自分の手で検証する</h2>\n    <p class="note">ターミナルで1行。返ってきた記録のハッシュと、このページの表のハッシュが一致するかを見る。</p>\n    <div class="cmd" id="verifycmd"></div>\n  </div>\n  <footer class="wrap" style="padding-left:0">公開コード: <a class="mono" href="https://github.com/ogasurfproject-jpg/horizon-shield" rel="noopener" style="color:var(--ink-2)">github.com/ogasurfproject-jpg/horizon-shield</a></footer>\n</div></section>\n<script>\nconst GATE = "https://gate.horizonshield.dev";\nfunction el(tag, cls, text){\n  const e = document.createElement(tag);\n  if (cls) e.className = cls;\n  if (text !== undefined) e.textContent = text;\n  return e;\n}\nfunction badgeClass(stat){\n  return stat === "pass" ? "b-pass" : (stat === "pending" || stat === "held") ? "b-pend" : "b-none";\n}\nasync function main(){\n  const box = document.getElementById("content");\n  const cmd = document.getElementById("verifycmd");\n  const ep = new URLSearchParams(location.search).get("endpoint");\n  box.textContent = "";\n  if (!ep){\n    box.appendChild(el("p", "note", "endpointが指定されていない。一覧から店名をクリックして来てくれ。"));\n    if (cmd) cmd.textContent = "curl -s \\"" + GATE + "/register\\"";\n    return;\n  }\n  if (cmd) cmd.textContent = "curl -s \\"" + GATE + "/history?endpoint=" + encodeURIComponent(ep) + "\\"";\n  try {\n    const reg = await (await fetch(GATE + "/register")).json();\n    const row = (Array.isArray(reg.rows) ? reg.rows : []).find(function(r){ return r.endpoint === ep; });\n    const card = el("div", "card");\n    if (!row){\n      card.appendChild(el("h1", null, "この住所はregisterに無い"));\n      card.appendChild(el("p", "note", "未掲載は不合格ではない。ここで測られたことが無い、それだけを意味する。"));\n      card.appendChild(el("p", "eprow mono", ep));\n      box.appendChild(card);\n      return;\n    }\n    const name = (row.operator_label && row.operator_label.ja) ? row.operator_label.ja : row.endpoint;\n    const h1 = el("h1", null, name);\n    const stat = (row.latest && row.latest.status) ? row.latest.status : "not yet measured";\n    const bg = el("span", "badge " + badgeClass(stat), stat);\n    h1.appendChild(bg);\n    card.appendChild(h1);\n    if (row.operator_label && row.operator_label.en) card.appendChild(el("p", "desc", row.operator_label.en));\n    card.appendChild(el("p", "eprow mono", row.endpoint));\n    if (typeof row.measurements === "number") card.appendChild(el("p", "note", "公開測定 " + row.measurements + " 回" + (row.first_at ? "、初回 " + String(row.first_at).slice(0,10) : "")));\n    if (row.operator_label && row.operator_label.url){\n      const a = el("a", "sitelink", "公式サイトを見る");\n      a.href = row.operator_label.url; a.rel = "noopener";\n      card.appendChild(a);\n    }\n    box.appendChild(card);\n\n    const hcard = el("div", "card");\n    hcard.appendChild(el("h2", null, "測定履歴（新しい順）"));\n    const hist = await (await fetch(GATE + "/history?endpoint=" + encodeURIComponent(ep))).json();\n    const entries = (hist && Array.isArray(hist.entries)) ? hist.entries.slice().reverse() : [];\n    if (!entries.length){\n      hcard.appendChild(el("p", "note", "保存された測定はまだ無い。"));\n    } else {\n      const t = el("table");\n      const tr0 = el("tr");\n      ["測定日時", "判定", "record_sha256"].forEach(function(h){ tr0.appendChild(el("th", null, h)); });\n      t.appendChild(tr0);\n      entries.forEach(function(e2){\n        const tr = el("tr");\n        tr.appendChild(el("td", "mono", String(e2.at || "").replace("T", " ").slice(0, 19)));\n        const td = el("td");\n        td.appendChild(el("span", "badge " + badgeClass(e2.status || ""), e2.status || "?"));\n        tr.appendChild(td);\n        tr.appendChild(el("td", "sha", e2.record_sha256 || ""));\n        t.appendChild(tr);\n      });\n      hcard.appendChild(t);\n    }\n    box.appendChild(hcard);\n  } catch (err){\n    box.appendChild(el("p", "note", "計器が読めなかった（" + err.message + "）。判定はしない。registerは " + GATE + "/register で直接読める。"));\n  }\n}\ndocument.addEventListener("DOMContentLoaded", main);\n</script>\n</body>\n</html>\n'

def main():
    contents = {}
    ok = True
    for path, old, new, name in EDITS:
        if path not in contents:
            contents[path] = open(path, encoding="utf-8").read()
        n = contents[path].count(old)
        print(f"[anchor] {name}: {n} occurrence(s) (expect 1)")
        if n != 1: ok = False
    exists = os.path.exists(MEMBER_PATH)
    print(f"[anchor] member.html not present yet: {'yes' if not exists else 'NO, already exists'} (expect yes)")
    if exists: ok = False
    if not ok:
        print("ABORT: anchor mismatch. Nothing written.")
        sys.exit(1)
    for path, old, new, name in EDITS:
        contents[path] = contents[path].replace(old, new, 1)

    w = contents["workers/hs-verify-gate/src/worker.js"]
    p = contents["verify-directory/index.html"]
    checks = [
        (w.count('url: "https://shield.the-horizons-innovation.com') == 5, "worker: 4 url fields added (1 pre-existing elsewhere, total 5)"),
        (p.count('member.html?endpoint=') == 1, "page: card links to member page"),
        (p.count("a.regname") == 2, "page: link css present"),
        ("record_sha256" in MEMBER_CONTENT, "member: hash column present"),
        ("掲載は推薦ではない" in MEMBER_CONTENT, "member: honesty note present"),
    ]
    tf = tempfile.NamedTemporaryFile("w", suffix=".js", delete=False, encoding="utf-8"); tf.write(w); tf.close()
    r = subprocess.run(["node", "--check", tf.name], capture_output=True, text=True)
    os.unlink(tf.name)
    checks.append((r.returncode == 0, "worker: node --check ok" + ("" if r.returncode == 0 else " :: " + r.stderr.strip()[:200])))
    m = re.search(r"<script>(.*?)</script>", MEMBER_CONTENT, re.S)
    tf = tempfile.NamedTemporaryFile("w", suffix=".js", delete=False, encoding="utf-8"); tf.write(m.group(1)); tf.close()
    r = subprocess.run(["node", "--check", tf.name], capture_output=True, text=True)
    os.unlink(tf.name)
    checks.append((r.returncode == 0, "member: node --check ok" + ("" if r.returncode == 0 else " :: " + r.stderr.strip()[:200])))
    allok = True
    for good, label in checks:
        print(("[ok]  " if good else "[FAIL] ") + label)
        allok = allok and good
    if not allok:
        print("ABORT: invariant failed. Nothing written.")
        sys.exit(1)
    if not APPLY:
        print("DRY-RUN成立。書き込みはしていない。--applyで適用する。")
        return
    for path in contents:
        open(path, "w", encoding="utf-8").write(contents[path])
        print(f"[written] {path}")
    open(MEMBER_PATH, "w", encoding="utf-8").write(MEMBER_CONTENT)
    print(f"[written] {MEMBER_PATH}")
    print("APPLY完了。")

if __name__ == "__main__":
    main()
